const output = items[0].json.stdout;
const result = JSON.parse(output);

// Retourner chaque fichier comme un item séparé avec le chemin complet formaté
return result.files.map(file => ({
  json: {
    page_number: file.page_number,
    file_name: file.file_name,
    file_path: file.file_path,
    // Nouveau champ avec le chemin formaté pour n8n
    formatted_path: `C:/hicham/data/MAGHREBAIL/document_pages/${file.file_name}`,
    total_pages: result.total_pages
  }
}));

const sortie = $input.first().json;

// Vérifier l'exécution
if (sortie.exitCode !== 0) {
  throw new Error(`Script Python en erreur (exitCode ${sortie.exitCode}) : ${sortie.stderr || sortie.stdout}`);
}

// Le JSON est indenté (multi-lignes) : on prend de la première "{" à la dernière "}"
const out = (sortie.stdout || '').trim();
const debut = out.indexOf('{');
const fin = out.lastIndexOf('}');
if (debut === -1 || fin === -1) {
  throw new Error('Aucun JSON trouvé dans stdout : ' + out);
}

const res = JSON.parse(out.slice(debut, fin + 1));
if (!res.success) {
  throw new Error('Extraction échouée : ' + res.error);
}

// "11 477,02" -> 11477.02
const num = (s) => s == null ? null : parseFloat(String(s).replace(/\s/g, '').replace(',', '.'));

// Un item n8n par ligne de facture (avec les infos de l'en-tête de la facture)
const items = [];
for (const f of res.factures) {
  for (const l of f.lignes) {
    items.push({
      json: {
        // En-tête facture
        reference: f.reference,
        date: f.date,
        numero_facture: f.numero,
        reference_document: f.reference_document,
        page: f.page,

        // Ligne de détail
        designation: l.designation,
        n_ech: l.n_ech,
        montant_ht: l.montant_ht,            // texte d'origine
        montant_ttc: l.montant_ttc,          // texte d'origine
        montant_ht_num: num(l.montant_ht),   // nombre
        montant_ttc_num: num(l.montant_ttc),

        // Totaux de la facture
        total_tva: f.total_tva,
        total_tva_num: num(f.total_tva),
        total_ttc: f.total_ttc,
        total_ttc_num: num(f.total_ttc),
        montant_lettres: f.montant_lettres,
        controle_ok: f.controle_ok,

        fichier: res.chemin,
      },
    });
  }
}

if (items.length === 0) {
  throw new Error('Aucune facture trouvée dans : ' + res.chemin);
}

return items;
